using System;using System.IO;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace Iris {
    public sealed partial class NotchWindow {
        static string AppVersion(){var version=typeof(NotchWindow).Assembly.GetName().Version;return version.Major+"."+version.Minor+"."+version.Build;}
        void BuildDataSettings(StackPanel panel){SettingsLabel(panel,L.T("Einstellungen und Versionswechsel"));var path=Text(L.T("Datenordner: ")+Path.Combine(root,dataFolder),11,muted);path.TextWrapping=TextWrapping.Wrap;path.Margin=new Thickness(0,0,0,8);panel.Children.Add(path);var button=Btn(L.T("Bisherige Iris-Daten verwenden …"),ChooseDataSource);button.Height=32;panel.Children.Add(button);var note=Text(string.IsNullOrEmpty(settingsStorageNote)?L.T("Für eine neue Version die bisherige Iris.exe auswählen. Einstellungen, Kacheln und Ablage bleiben im bisherigen Datenordner. Wirksam beim nächsten Start."):settingsStorageNote,11,muted);note.TextWrapping=TextWrapping.Wrap;note.Margin=new Thickness(0,8,0,0);panel.Children.Add(note);}
        void ChooseDataSource(){if(uiTesting||shuttingDown)return;var dialog=new Microsoft.Win32.OpenFileDialog{Title=L.T("Iris.exe aus deinem bisherigen Programmordner auswählen"),Filter="Iris|Iris.exe",CheckFileExists=true};int generation=++dataSelectionGeneration;var owner=settings;if(dialog.ShowDialog(owner)!=true)return;string selected=Path.GetDirectoryName(dialog.FileName);Task.Factory.StartNew(delegate{return DataLocation.Validate(DataLocation.Resolve(selected,false));}).ContinueWith(task=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke(new Action(delegate{if(shuttingDown||generation!=dataSelectionGeneration||settings!=owner)return;if(task.IsFaulted){ShowIntegrationResult(L.T("Datenordner"),task.Exception.GetBaseException().Message);return;}ShowDataReview(task.Result);}));});}
        void ShowDataReview(string directory){if(addonWindow!=null){addonWindow.Activate();return;}OpenAddonWindow(L.T("Bisherige Daten verwenden"));RenderDataReview(directory);}
        void RenderDataReview(string directory){var panel=AddonPanel();panel.Children.Add(AddonNote(L.T("Beim nächsten Start verwendet diese Fassung den bisherigen Datenordner. Deine Einstellungen, Kachelbelegungen, Verbindungen und Ablage bleiben dort. Es werden keine persönlichen Daten kopiert, verschoben oder gelöscht.")));panel.Children.Add(AddonNote(directory));panel.Children.Add(AddonNote(L.T("Den bisherigen Programmordner deshalb behalten. Vor dem nächsten Start die alte Iris-Fassung über das Symbol im Windows-Infobereich beenden. Beide Fassungen teilen anschließend denselben Datenbestand.")));var status=AddonNote("");var apply=Btn(L.T("Diesen Datenordner beim nächsten Start verwenden"),delegate{try{string targetRoot=uiTesting?Path.Combine(root,"Data-qa","data-switch-runtime"):root;Directory.CreateDirectory(targetRoot);DataLocation.Use(targetRoot,directory);status.Text=L.T("Gespeichert. Iris beim nächsten Mal aus diesem neuen Programmordner starten. Die bisherige Sitzung bleibt unverändert.");}catch(Exception ex){status.Text=L.T("Nicht übernommen: ")+ex.Message;}});apply.Height=38;panel.Children.Add(apply);panel.Children.Add(status);ShowAddonDialogPage("data-review",panel,1);}
    }
}
